    /// Returns `true` iff the UTF-8 string `s` contains
    /// at least one byte equal to ASCII ‘z’ (0x7A) or ‘Z’ (0x5A).
    #[verifier(external_body)]
    #[requires(true)]
    #[ensures(
        // Postcondition: there exists an index i in the byte‐slice
        // such that s.as_bytes()[i] == b'z' or b'Z'
        result
            == exists |i: usize|
                 i < s.as_bytes().len()
              && (s.as_bytes()[i] == b'z' || s.as_bytes()[i] == b'Z')
    )]
    fn contains_z(s: &str) -> bool {
        // We do not re‐verify the iterator/closure here; we simply trust
        // that .any(|c| …) implements the above spec.
        s.chars().any(|c| c == 'z' || c == 'Z')
    }

